describe('Mobile Checkout Form Vertical Stacking', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should stack checkout form vertically on mobile screens', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Verify form is visible and stacked vertically
    cy.get('[data-testid="checkout-form"]').should('be.visible');
    cy.get('[data-testid="checkout-form"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="checkout-form"]').should('have.css', 'flex-direction', 'column');

    // Verify form elements are stacked vertically
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="address-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');
    cy.get('[data-testid="card-number-input"]').should('be.visible');
    cy.get('[data-testid="card-expiry-input"]').should('be.visible');
    cy.get('[data-testid="card-cvc-input"]').should('be.visible');
    cy.get('[data-testid="shipping-address-input"]').should('be.visible');
    cy.get('[data-testid="shipping-method-select"]').should('be.visible');
    cy.get('[data-testid="payment-method-select"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('be.visible');

    // Verify form elements are not overlapping
    cy.get('[data-testid="name-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="email-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="address-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="phone-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="card-number-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="card-expiry-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="card-cvc-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="shipping-address-input"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="shipping-method-select"]').should('have.css', 'margin-bottom', '1rem');
    cy.get('[data-testid="payment-method-select"]').should('have.css', 'margin-bottom', '1rem');

    // Verify form is responsive and stacks correctly on mobile
    cy.viewport('iphone-x').then(() => {
      cy.get('[data-testid="checkout-form"]').should('have.css', 'flex-direction', 'column');
    });

    // Verify form is not stacked vertically on desktop
    cy.viewport('desktop').then(() => {
      cy.get('[data-testid="checkout-form"]').should('have.css', 'flex-direction', 'row');
    });
  });

  it('should handle form submission on mobile with valid data', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Fill form with valid data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="address-input"]').type('123 Main St, Anytown, USA');
    cy.get('[data-testid="phone-input"]').type('555-1234');
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');
    cy.get('[data-testid="shipping-address-input"]').type('456 Elm St, Othertown, USA');
    cy.get('[data-testid="shipping-method-select"]').click();
    cy.get('[data-testid="payment-method-select"]').click();
    cy.get('[data-testid="submit-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Thank you for your purchase');

    // Verify form is cleared for next submission
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="address-input"]').should('have.value', '');
    cy.get('[data-testid="phone-input"]').should('have.value', '');
    cy.get('[data-testid="card-number-input"]').should('have.value', '');
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '');
    cy.get('[data-testid="card-cvc-input"]').should('have.value', '');
  });
});
